{
  "$schema": "https://datapackage.org/profiles/2.0/datapackage.json",
  "name": "power-log-ride-generated-android-health",
  "id": "generated-android-health",
  "title": "Power Log ride",
  "created": "2026-09-09T00:00:30Z",
  "description": "One Power Log ride: controller readings, GPS fixes, Health values and ride events, each in its own table, with the ride metadata and its sources.",
  "powerLog:ride": {
    "startedAt": "2026-09-09T00:00:00Z",
    "endedAt": "2026-09-09T00:00:10Z",
    "elapsedSeconds": 10,
    "timerSeconds": 10,
    "ownerTiming": {
      "timestamp": "2026-09-09T00:00:10Z",
      "elapsedSeconds": 10,
      "timerSeconds": 10
    },
    "indoor": false,
    "interrupted": false,
    "watchEnabled": false,
    "saveToHealth": true,
    "recordGPS": true,
    "sport": "cycling",
    "subSport": "e_biking",
    "health": {
      "provider": "healthConnect",
      "state": "saved",
      "workoutUUID": "generated-provider-parent",
      "export": null
    },
    "example": false,
    "sampleHz": 2,
    "batteryConsumptionSource": "controller"
  },
  "powerLog:batteryConsumption": {
    "status": "unavailable",
    "reason": "No controller telemetry."
  },
  "powerLog:sources": {
    "connections": [],
    "gps": [],
    "health": [
      "phone"
    ]
  },
  "resources": [
    {
      "name": "telemetry",
      "type": "table",
      "path": "telemetry.csv",
      "format": "csv",
      "mediatype": "text/csv",
      "encoding": "utf-8",
      "dialect": {
        "header": true,
        "delimiter": ",",
        "lineTerminator": "\n"
      },
      "schema": {
        "fields": [
          {
            "name": "timestamp",
            "type": "datetime",
            "description": "Original reading time in the source clock, as retained"
          },
          {
            "name": "elapsedSeconds",
            "type": "number",
            "description": "Time on the ride timeline",
            "powerLog:unit": "s"
          },
          {
            "name": "activeInterval",
            "type": "integer",
            "description": "Activity interval, numbered from 1; empty while paused"
          },
          {
            "name": "run",
            "type": "integer",
            "description": "Continuous run of readings, numbered from 1 in order of first appearance"
          },
          {
            "name": "connection",
            "type": "integer",
            "description": "Controller connection, numbered as in powerLog:sources.connections"
          },
          {
            "name": "humanPowerW",
            "type": "number",
            "description": "Rider power reported by the controller",
            "powerLog:unit": "W"
          },
          {
            "name": "cadenceRpm",
            "type": "number",
            "description": "Crank cadence reported by the controller, smoothed",
            "powerLog:unit": "/min"
          },
          {
            "name": "motorInputPowerW",
            "type": "number",
            "description": "Battery input power: battery voltage × battery current; not motor output or rider power",
            "powerLog:unit": "W"
          },
          {
            "name": "batteryVoltageV",
            "type": "number",
            "description": "Battery voltage",
            "powerLog:unit": "V"
          },
          {
            "name": "batteryCurrentA",
            "type": "number",
            "description": "Battery current; negative under regeneration",
            "powerLog:unit": "A"
          },
          {
            "name": "motorCurrentA",
            "type": "number",
            "description": "Motor current",
            "powerLog:unit": "A"
          },
          {
            "name": "motorRpm",
            "type": "number",
            "description": "Motor speed; not crank cadence",
            "powerLog:unit": "/min"
          },
          {
            "name": "pedalTorqueNm",
            "type": "number",
            "description": "Pedal torque",
            "powerLog:unit": "N.m"
          },
          {
            "name": "controllerTempC",
            "type": "number",
            "description": "Controller temperature; not ambient temperature",
            "powerLog:unit": "Cel"
          },
          {
            "name": "motorTempC",
            "type": "number",
            "description": "Motor temperature; not ambient temperature",
            "powerLog:unit": "Cel"
          },
          {
            "name": "consumedAh",
            "type": "number",
            "description": "Charge counter of the controller; not ride consumption",
            "powerLog:unit": "A.h"
          },
          {
            "name": "consumedWh",
            "type": "number",
            "description": "Energy counter of the controller; not ride consumption",
            "powerLog:unit": "W.h"
          },
          {
            "name": "throttleVoltageV",
            "type": "number",
            "description": "Throttle voltage",
            "powerLog:unit": "V"
          },
          {
            "name": "faultCode",
            "type": "integer",
            "description": "Fault code in the vocabulary of the connection's vendor"
          },
          {
            "name": "assistLevel",
            "type": "integer",
            "description": "Assist level reported by the controller"
          },
          {
            "name": "controllerSpeedMps",
            "type": "number",
            "description": "Controller speed, normalized for a known controller profile",
            "powerLog:unit": "m/s"
          },
          {
            "name": "controller.raceMode",
            "type": "integer",
            "description": "Controller race mode",
            "powerLog:vendor": "controller"
          },
          {
            "name": "controller.speedRaw",
            "type": "number",
            "description": "Controller speed field divided by 100; its unit depends on the controller profile",
            "powerLog:vendor": "controller"
          }
        ],
        "missingValues": [
          ""
        ]
      }
    },
    {
      "name": "battery_consumption",
      "type": "table",
      "path": "battery-consumption.csv",
      "format": "csv",
      "mediatype": "text/csv",
      "encoding": "utf-8",
      "dialect": {
        "header": true,
        "delimiter": ",",
        "lineTerminator": "\n"
      },
      "schema": {
        "fields": [
          {
            "name": "timestamp",
            "type": "datetime",
            "description": "Original controller timestamp."
          },
          {
            "name": "elapsedSeconds",
            "type": "number",
            "description": "Time on the ride timeline.",
            "powerLog:unit": "s"
          },
          {
            "name": "controllerEnergyWh",
            "type": "number",
            "description": "Energy used (controller). Ride consumption from changes in the controller energy counter, starting at zero.",
            "powerLog:unit": "Wh"
          },
          {
            "name": "controllerChargeAh",
            "type": "number",
            "description": "Charge used (controller). Ride consumption from changes in the controller charge counter, starting at zero.",
            "powerLog:unit": "Ah"
          },
          {
            "name": "calculatedEnergyWh",
            "type": "number",
            "description": "Energy used (calc). Calculated by Power Log by integrating positive battery voltage × current during this ride.",
            "powerLog:unit": "Wh"
          },
          {
            "name": "calculatedChargeAh",
            "type": "number",
            "description": "Charge used (calc). Calculated by Power Log by integrating positive battery current during this ride.",
            "powerLog:unit": "Ah"
          }
        ],
        "missingValues": [
          ""
        ]
      }
    },
    {
      "name": "gps",
      "type": "table",
      "path": "gps.csv",
      "format": "csv",
      "mediatype": "text/csv",
      "encoding": "utf-8",
      "dialect": {
        "header": true,
        "delimiter": ",",
        "lineTerminator": "\n"
      },
      "schema": {
        "fields": [
          {
            "name": "timestamp",
            "type": "datetime",
            "description": "Original fix time in the source clock, as retained"
          },
          {
            "name": "elapsedSeconds",
            "type": "number",
            "description": "Time on the ride timeline",
            "powerLog:unit": "s"
          },
          {
            "name": "activeInterval",
            "type": "integer",
            "description": "Activity interval, numbered from 1; empty while paused"
          },
          {
            "name": "run",
            "type": "integer",
            "description": "Continuous run of fixes, numbered from 1 in order of first appearance; a barrier fix is its own run"
          },
          {
            "name": "source",
            "type": "string",
            "description": "GPS producer: phone or watch"
          },
          {
            "name": "latitude",
            "type": "number",
            "description": "Latitude",
            "powerLog:unit": "deg"
          },
          {
            "name": "longitude",
            "type": "number",
            "description": "Longitude",
            "powerLog:unit": "deg"
          },
          {
            "name": "altitudeMeters",
            "type": "number",
            "description": "Altitude above mean sea level",
            "powerLog:unit": "m"
          },
          {
            "name": "verticalAccuracyM",
            "type": "number",
            "description": "Vertical accuracy of altitudeMeters",
            "powerLog:unit": "m"
          },
          {
            "name": "originalAltitudeMeters",
            "type": "number",
            "description": "Original provider altitude in originalAltitudeDatum",
            "powerLog:unit": "m"
          },
          {
            "name": "originalVerticalAccuracyM",
            "type": "number",
            "description": "Original provider vertical accuracy",
            "powerLog:unit": "m"
          },
          {
            "name": "originalAltitudeDatum",
            "type": "string",
            "description": "Datum of the original altitude: msl, wgs84Ellipsoid or unknown"
          },
          {
            "name": "horizontalAccuracyM",
            "type": "number",
            "description": "Horizontal accuracy",
            "powerLog:unit": "m"
          },
          {
            "name": "speedMps",
            "type": "number",
            "description": "GPS speed",
            "powerLog:unit": "m/s"
          },
          {
            "name": "speedAccuracyMps",
            "type": "number",
