            "powerLog:unit": "deg"
          },
          {
            "name": "courseAccuracyDegrees",
            "type": "number",
            "description": "Accuracy of courseDegrees",
            "powerLog:unit": "deg"
          }
        ],
        "missingValues": [
          ""
        ]
      }
    },
    {
      "name": "health",
      "type": "table",
      "path": "health.csv",
      "format": "csv",
      "mediatype": "text/csv",
      "encoding": "utf-8",
      "dialect": {
        "header": true,
        "delimiter": ",",
        "lineTerminator": "\n"
      },
      "schema": {
        "fields": [
          {
            "name": "timestamp",
            "type": "datetime",
